SubscriptionsPage::~SubscriptionsPage(){if(pending_&&pending_->receiver){pending_->receiver->request_stop();}}
void SubscriptionsPage::beginSession(quint64 session,quint64 page){const auto old=pending_;pending_.reset();catalogPending_.reset();session_=session;page_=page;generation_=0;normal_=false;choices_.clear();cancelling_=false;updating_=true;const auto rev=++revision_;if(old&&old->receiver){old->receiver->request_stop();}QPointer<SubscriptionsPage> alive(this);choicesBox_->clear();if(!alive||revision_!=rev){return;}table_->setRowCount(0);if(!alive||revision_!=rev){return;}updating_=false;status_->setText(tr("Refresh to read saved subscriptions."));if(!alive||revision_!=rev){return;}updateControls();if(alive&&old){emit cancelRequested(old->key);}}
void SubscriptionsPage::invalidateSession(){const auto old=pending_;pending_.reset();catalogPending_.reset();session_=page_=generation_=0;normal_=false;choices_.clear();++revision_;if(old&&old->receiver){old->receiver->request_stop();}QPointer<SubscriptionsPage> alive(this);updateControls();if(alive&&old){emit cancelRequested(old->key);}}
void SubscriptionsPage::setAvailable(bool available,bool preview){available_=available;preview_=preview;updateControls();}
void SubscriptionsPage::updateControls(){QPointer<SubscriptionsPage> alive(this);const auto rev=revision_;const auto idle=[this]{return available_&&!updating_&&session_&&page_&&!pending_&&!catalogPending_;};refresh_->setEnabled(idle());if(!alive||revision_!=rev){return;}choicesBox_->setEnabled(idle());if(!alive||revision_!=rev){return;}const auto at=choicesBox_->currentIndex();const bool chosen=at>=0&&static_cast<std::size_t>(at)<choices_.size();check_->setEnabled(idle()&&generation_&&!preview_&&normal_&&chosen&&choices_[static_cast<std::size_t>(at)].canCheck);if(!alive||revision_!=rev){return;}cancel_->setEnabled(pending_&&pending_->key.action==SubscriptionAction::Check&&!cancelling_);if(!alive||revision_!=rev){return;}const auto mutate=[&]{return idle()&&!preview_&&normal_&&chosen&&choices_[static_cast<std::size_t>(at)].canCheck&&!table_->selectionModel()->selectedRows().isEmpty();};for(auto* b:{read_,unread_,erase_}){b->setEnabled(mutate());if(!alive||revision_!=rev){return;}}}
void SubscriptionsPage::refresh(){if(available_&&session_&&page_&&!pending_&&!catalogPending_){emit catalogRequested({session_,page_,0});}}
void SubscriptionsPage::setCatalogPending(SubscriptionCatalogKey key){if(key.session!=session_||key.page!=page_){return;}catalogPending_=key;const auto rev=++revision_;QPointer<SubscriptionsPage> alive(this);status_->setText(tr("Reading saved subscriptions…"));if(alive&&revision_==rev){updateControls();}}
void SubscriptionsPage::setPending(const SubscriptionCommand& command){if(command.key.session!=session_||command.key.page!=page_){return;}pending_=command;cancelling_=command.receiver&&command.receiver->stop_requested();const auto rev=++revision_;QPointer<SubscriptionsPage> alive(this);status_->setText(command.key.action==SubscriptionAction::Check?tr("Checking subscription…"):tr("Reading saved results…"));if(alive&&revision_==rev){updateControls();}}
void SubscriptionsPage::request(SubscriptionAction action){const auto at=choicesBox_->currentIndex();if(!available_||updating_||!generation_||pending_||catalogPending_||at<0||static_cast<std::size_t>(at)>=choices_.size()){return;}const auto& choice=choices_[static_cast<std::size_t>(at)];if(action!=SubscriptionAction::ReadResults&&(preview_||!normal_||!choice.canCheck)){return;}SubscriptionCommand command;command.key={session_,page_,0,generation_,choice.key,action};command.receiver=std::make_shared<std::stop_source>();if(action!=SubscriptionAction::Check&&action!=SubscriptionAction::ReadResults){for(const auto& row:table_->selectionModel()->selectedRows()){const auto key=table_->item(row.row(),0)->data(Qt::UserRole).toByteArray();if(key.size()!=10||command.resultKeys.size()==MaximumSubscriptionRows){return;}command.resultKeys.push_back(key);}if(command.resultKeys.empty()){return;}}
  pending_=command;cancelling_=false;const auto rev=++revision_;QPointer<SubscriptionsPage> alive(this);if(action==SubscriptionAction::ReadResults){table_->setRowCount(0);if(!alive||revision_!=rev){return;}}updateControls();if(alive&&revision_==rev){emit commandRequested(std::move(command));}}
void SubscriptionsPage::cancel(){if(!pending_||pending_->key.action!=SubscriptionAction::Check||cancelling_){return;}const auto command=*pending_;cancelling_=true;if(command.receiver){command.receiver->request_stop();}QPointer<SubscriptionsPage> alive(this);status_->setText(tr("Cancelling…"));if(!alive){return;}updateControls();if(alive){emit cancelRequested(command.key);}}
void SubscriptionsPage::setCatalog(SubscriptionCatalogPresentation packet){if(!packet||!catalogPending_||packet->key!=*catalogPending_||packet->key.session!=session_||packet->key.page!=page_){return;}catalogPending_.reset();const auto rev=++revision_;generation_=packet->generation;normal_=packet->normalNetwork;updating_=true;const bool valid=packet->sources.size()<=MaximumSubscriptionRows&&std::ranges::all_of(packet->sources,[](const auto& row){return row.key.sid.size()==10&&row.key.publicKey.size()<=4096&&row.key.singletonKey.size()<=2048&&row.name.size()<=2048&&row.status.size()<=512;});choices_=valid?packet->sources:std::vector<SubscriptionChoice>{};if(!valid){normal_=false;}QPointer<SubscriptionsPage> alive(this);choicesBox_->clear();if(!alive||revision_!=rev){return;}table_->setRowCount(0);if(!alive||revision_!=rev){return;}if(valid){for(const auto& row:packet->sources){choicesBox_->addItem(row.name+QStringLiteral(" — ")+row.status);if(!alive||revision_!=rev){return;}}}updating_=false;status_->setText(!packet->failure.isEmpty()?packet->failure.left(512):choices_.empty()?tr("No saved subscriptions."):preview_||!normal_?tr("Saved subscription history is read only in this session."):tr("Select a subscription to read its saved results. Check now performs one check."));if(!alive||revision_!=rev){return;}updateControls();if(alive&&revision_==rev&&!choices_.empty()){request(SubscriptionAction::ReadResults);}}
void SubscriptionsPage::setResult(SubscriptionPresentation packet){if(!packet||!pending_||packet->key!=pending_->key||packet->key.session!=session_||packet->key.page!=page_){return;}if(packet->state==SubscriptionState::Started){return;}const bool stopped=pending_->receiver&&pending_->receiver->stop_requested();pending_.reset();cancelling_=false;const auto rev=++revision_;QPointer<SubscriptionsPage> alive(this);if(packet->state==SubscriptionState::Ready&&(!stopped||packet->committed)&&packet->rows.size()<=MaximumSubscriptionRows&&std::ranges::all_of(packet->rows,[](const auto& row){return row.key.size()==10;})){table_->setRowCount(static_cast<int>(packet->rows.size()));if(!alive||revision_!=rev){return;}for(std::size_t i=0;i<packet->rows.size();++i){const auto& row=packet->rows[i];const std::array<QString,7> cells{row.read?tr("Yes"):tr("No"),row.title,row.size,row.seeds,row.peers,row.publication,row.link};for(int column=0;column<7;++column){auto* item=new QTableWidgetItem(cells[static_cast<std::size_t>(column)].left(2048));if(column==0){item->setData(Qt::UserRole,row.key);}table_->setItem(static_cast<int>(i),column,item);if(!alive||revision_!=rev){return;}}}}
  status_->setText(packet->committed&&stopped?tr("Results were saved before cancellation."):stopped||packet->state==SubscriptionState::Cancelled?tr("Cancelled; saved history is unchanged."):packet->message.left(512));if(alive&&revision_==rev){updateControls();}}
void SubscriptionsPage::refuseCatalog(SubscriptionCatalogKey key){auto packet=std::make_shared<SubscriptionCatalogPacket>();packet->key=key;packet->failure=tr("Saved subscriptions could not be read; refresh when the current operation finishes.");setCatalog(std::move(packet));}
void SubscriptionsPage::refuseCommand(const SubscriptionCommand& command){auto packet=std::make_shared<SubscriptionPacket>();packet->key=command.key;packet->state=SubscriptionState::Rejected;packet->message=tr("This subscription operation could not start; refresh before retrying.");setResult(std::move(packet));}
